import { Tab as BaseTab, TabGroup as BaseTabGroup, TabList as BaseTabList, TabPanel as BaseTabPanel, } from "terracotta";
import "./Tabs.css";
export const Tab = props => <BaseTab data-start-tab {...props}/>;
export const TabGroup = props => (<BaseTabGroup data-start-tab-group {...props}/>);
export const TabPanel = props => (<BaseTabPanel data-start-tab-panel {...props}/>);
export const TabList = props => <BaseTabList data-start-tab-list {...props}/>;
